using System.Windows;
using System.Windows.Controls;
using TrueBIM.App.UI;
using TrueBIM.App.UI.DesignSystem;

namespace TrueBIM.App.Modules.RebarDetailing;

public sealed class RebarDetailingGuideWindow : TrueBimWindow
{
    public RebarDetailingGuideWindow()
    {
        Title = "Методичка: оформление вертикальных сечений";
        Width = 840; Height = 720; MinWidth = 650; MinHeight = 450;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;
        StackPanel body = new() { Margin = new Thickness(16) };
        Add("1. Подготовьте виды", "Откройте готовое вертикальное сечение либо выделите виды в диспетчере проекта или видовые экраны на листе. Проверьте масштаб, шаблон, глубину и видимость арматуры. Горизонтальные и наклонные виды не обрабатываются.");
        Add("2. Выберите вариант", "В одном запуске используйте один вариант: прямой, Г-образный в одну сторону или Г-образный в разные стороны. Зеркальные загибы в одну сторону относятся ко второму варианту. Отметьте нужные виды в таблице.");
        Add("3. Настройте оформление", "Галочки отдельно включают марки, размеры бетона, шаг и привязки арматуры, отметки, обрывы и шпильки. Выберите линейный размерный стиль. Резервные типы марок и отметок используются, если подходящий тип нельзя подобрать по проекту.");
        Add("4. Обрывы и обрезка", "Контур обрывов проходит на 250 мм снаружи стены и видимой арматуры, чтобы не закрывать стержни. Поиск бетона идёт от верхнего левого угла против часовой стрелки. При необходимости прямоугольная обрезка расширяется до крайних линий обрывов с запасом 30 мм; глубина сечения и масштаб сохраняются. Для фигурной или разделённой обрезки, требующей расширения, выводится пояснение и изменения вида отменяются.");
        Add("5. Размеры и марки", "Левые цепочки привязываются к арматуре у левой грани. Равный шаг отображается штатной формулой Revit. Верхняя вертикальная привязка идёт к торцу прямого стержня либо верхней грани горизонтальной ветви Г-образного. Регулярный массив получает марку у формулы; нерегулярный — количество и выноску к нижнему стержню. Разные формы и типы разделяются.");
        Add("6. Шпильки и выноски", "Для шпилек загрузите (Узел) Арматура • Ш1, тип A240. A = толщина стены − 50 мм; при толщине 250 мм A = 200 мм. Шпильки ставятся по центру стены от нижнего горизонтального ряда через ряд. Выноска содержит толщину и диаметр вертикальной арматуры, например t250_d12, и «в шахм. порядке». Начала полок создаваемых типовых выносок выравниваются по правой границе обрезки.");
        Add("7. Подписи плит", "Измените верхнюю и нижнюю строки выносок. Две пустые строки отключают выноску. {том} заменяется маркой тома из имени связи. Нужны семейства (Узел) Область обрыва • 1/2/3 с типом M<масштаб> и (Аннотация) Выноска. Семейства автоматически не загружаются.");
        Add("8. Повторный запуск и отмена", "«Заменить существующие» пересоздаёт выбранные размеры, марки и отметки, а также собственные детали команды. Ручные детали сохраняются. Закреплённые, сгруппированные или заблокированные аннотации останавливают замену. Количество записывается только в пустой или прежний числовой комментарий; текст сохраняется. Ошибка откатывает весь проблемный вид, запуск можно отменить одной командой Revit.");
        Add("9. Ограничения", "Шпильки являются компонентами оформления, а не модельной арматурой. Связи читаются с Revit 2024; размеры арматуры создаются для текущего проекта. В Revit 2019–2023 обрабатываются элементы текущего проекта. После оформления проверьте результат и сообщения команды.");
        Button close = TrueBimUi.CreateSecondaryButton("Закрыть", TrueBimIcon.Close, (_, _) => Close());
        close.IsCancel = true;
        ApplyTrueBimShell(TrueBimUi.CreateHeader(Title, "Подготовка, настройки и проверка результата", TrueBimIcon.Help), null,
            new ScrollViewer { Content = body, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }, null,
            TrueBimUi.CreateFooter(null, close));

        void Add(string title, string text)
        {
            body.Children.Add(new TextBlock { Text = title, FontSize = 17, FontWeight = FontWeights.SemiBold,
                TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 12, 0, 6) });
            body.Children.Add(new TextBlock { Text = text, FontSize = 14, TextWrapping = TextWrapping.Wrap });
        }
    }
}
